 $P(0,0): 2f(0)=4f(0) \implies f(0)=0$  $P(0,x): f(x)+f(-x)=2f(x) \implies f(-x)=f(x)$  $P(x,x): f(2x)=4f(x)$  $P(x+y,z): f(x+y+z)+f(x+y-z)= 2f(x+y)+2f(z)$  $P(y+z,x): f(x+y+z)+ f(-x+y+z) = 2f(y+z)+2f(x)$  $P(z+x,y): f(x+y+z)+f(x-y+z) = 2f(z+x)+2f(y)$ Summing,  $3f(x+y+z)=2\left[f(x+y)+f(y+z)+f(z+x) \right] +2f(x)+2f(y)+2f(z)$  $P(x,y-z): f(x+y-z)+f(x-y+z)=2f(x)+2f(y-z)$  $P(y,z-x): f(-x+y+z)+f(x+y-z)=2f(y)+2f(z-x)$  $P(z,x-y): f(x-y+z)+f(-x+y+z)=2f(z)+2f(x-y)$ Summing,  $f(x+y-z)+f(-x+y+z)+f(x-y+z)=f(x-y)+f(y-z)+f(z-x)+f(x)+f(y)+f(z)$ Thus, 
\begin{align*}
    3f(x+y+z) &=2\left[f(x+y)+f(y+z)+f(z+x) \right] +2f(x)+2f(y)+2f(z) - \left[ f(x+y-z) + f(-x+y+z)+f(x-y+z) \right]
    &= 3\left[f(x+y)+f(y+z)+f(z+x) \right] +f(x)+f(y)+f(z)-\left[ (f(x+y)+f(x-y))+(f(y+z)+f(y-z))+(f(z+x)+f(z-x)) \right] 
    &=3\left[f(x+y)+f(y+z)+f(z+x) \right]-3\left[f(x)+f(y)+f(z)\right] 
\end{align*}

